<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue'
import Icon from './Icon.vue'
import JavaPicker from './JavaPicker.vue'
import ModManager from './ModManager.vue'
import ResourceBrowser from './ResourceBrowser.vue'
import type { ResourceKind } from '../../shared/resources'
import { api, busy, data, pages, run, toast } from '../store'
import type { Instance, InstanceOptions, JavaInfo, Release, Settings, Tab } from '../../shared/model'
import { loaderKinds,loaderNames,requiredJava,type LoaderKind,type LoaderRelease } from '../../shared/loaders'
import { accentPresets } from '../../shared/appearance'
import { selectInstances } from '../../shared/instance-list'
const props=defineProps<{tab:Tab;paneId:string}>()
const emit=defineEmits<{navigate:[page:Tab['page']];login:[]}>()
const scroller=ref<HTMLElement>()
const tab=computed(()=>props.tab)
function view<T extends string|boolean>(key:string,fallback:T){return computed({get:()=>props.tab.view[key]===undefined?fallback:props.tab.view[key] as T,set:(value:T)=>{props.tab.view[key]=value}})}
const filter=view<string>('instanceFilter','all')
const loaderFilter=view<string>('loaderFilter',''),sortOrder=view<string>('sortOrder','favorite')
const groups=computed(()=>[...new Set(data.instances.map(i=>i.group).filter(Boolean))])
const filtered=computed(()=>selectInstances(data.instances,{query:tab.value.query,group:tab.value.group,filter:filter.value,loader:loaderFilter.value,sort:sortOrder.value}))
const running=computed(()=>data.instances.filter(i=>i.running).length)
const editor=ref<Instance|null>(null),modInstance=ref<Instance|null>(null)
const downloadKind=view<string>('downloadKind',props.tab.page==='install'?'game':'game')
const resourceKind=computed(()=>downloadKind.value as ResourceKind)
const cfKey=ref(''),cfConfigured=ref(false)
async function saveCf(){const ok=await run('cf-config','resource.configure',cfKey.value);if(ok!==undefined){cfConfigured.value=ok;cfKey.value='';toast(ok?'CurseForge 密钥已保存':'CurseForge 密钥已清除')}}
function openModDownloads(){if(!modInstance.value)return;props.tab.view.resourceInstance=modInstance.value.id;props.tab.view.downloadKind='mod';modInstance.value=null;emit('navigate','resources')}
const options=reactive<InstanceOptions>({name:'',group:'',favorite:false,memory:4096,java:'',isolated:false,protected:false,memoryMode:'inherit'})
const removeTarget=ref<Instance|null>(null)
const settings=reactive<Settings>({...data.state.settings})
watch(()=>data.state.settings,(v,old)=>{for(const key of Object.keys(v) as (keyof Settings)[])if(!old||settings[key]===old[key])Object.assign(settings,{[key]:v[key]})},{deep:true})
async function changeAppearance(patch: Partial<Pick<Settings,'theme'|'accent'|'reduceMotion'|'fontScale'>>) {
  Object.assign(settings,patch)
  try { await api('appearance.save',{theme:settings.theme,accent:settings.accent,reduceMotion:settings.reduceMotion,fontScale:settings.fontScale}) }
  catch(e:any) { Object.assign(settings,{theme:data.state.settings.theme,accent:data.state.settings.accent,reduceMotion:data.state.settings.reduceMotion,fontScale:data.state.settings.fontScale});toast('外观保存失败：'+e.message) }
}
const java=ref<JavaInfo[]>([])
const versions=ref<Release[]>([]), versionSearch=view<string>('versionSearch',''), showSnapshots=view<boolean>('showSnapshots',false), selectedVersion=view<string>('selectedVersion',''), source=view<string>('source',''), loadingVersions=ref(false), versionError=ref('')
const loader=view<string>('loader',props.tab.view.fabric?'fabric':'vanilla'),loaderVersion=view<string>('loaderVersion',''),loaderSource=view<string>('loaderSource','auto'),fabricApi=view<boolean>('fabricApi',false),installJava=view<string>('installJava','')
const loaderVersions=ref<LoaderRelease[]>([]),loadingLoaders=ref(false),loaderError=ref(''),showLoaderTests=view<boolean>('showLoaderTests',false)
const visibleLoaders=computed(()=>loaderVersions.value.filter(v=>showLoaderTests.value||v.stable))
const javaRule=computed(()=>requiredJava(selectedVersion.value,loader.value as LoaderKind))
let loaderGeneration=0
async function loadLoaders(refresh=false){const generation=++loaderGeneration;loaderVersions.value=[];loaderError.value='';if(loader.value==='vanilla'||!selectedVersion.value){loadingLoaders.value=false;return}loadingLoaders.value=true;try{const values=await api<LoaderRelease[]>('loaders.list',{minecraft:selectedVersion.value,loader:loader.value,source:loaderSource.value,refresh});if(generation!==loaderGeneration)return;loaderVersions.value=values;if(!values.some(v=>v.version===loaderVersion.value))loaderVersion.value=(values.find(v=>v.recommended)||values.find(v=>v.stable)||values[0])?.version||'';if(!values.some(v=>v.stable))showLoaderTests.value=true}catch(e:any){if(generation===loaderGeneration)loaderError.value=e.message}finally{if(generation===loaderGeneration)loadingLoaders.value=false}}
watch([selectedVersion,loader,loaderSource],()=>{if(loader.value!=='fabric')fabricApi.value=false;void loadLoaders()})
watch(()=>props.tab.id,()=>loadLoaders())
const releaseList=computed(()=>versions.value.filter(v=>(showSnapshots.value||v.type==='release')&&v.id.toLowerCase().includes(versionSearch.value.toLowerCase())).slice(0,120))
const plugins=ref<any[]>([])
const logFilter=view<string>('logFilter',''), logScope=view<string>('logScope',''), onlyErrors=view<boolean>('onlyErrors',false), logElement=ref<HTMLElement>(), autoScroll=view<boolean>('autoScroll',true)
const visibleLogs=computed(()=>data.logs.filter(l=>(!onlyErrors.value||l.level==='error')&&(!logScope.value||l.instanceId===logScope.value)&&(!logFilter.value||l.text.toLowerCase().includes(logFilter.value.toLowerCase()))).slice(-500))
watch(()=>data.logs.at(-1),async()=>{if(autoScroll.value){await nextTick();if(logElement.value)logElement.value.scrollTop=logElement.value.scrollHeight}})
async function loadVersions(){loadingVersions.value=true;versionError.value='';try{versions.value=await api<Release[]>('versions');if(!selectedVersion.value)selectedVersion.value=versions.value.find(v=>v.type==='release')?.id||''}catch(e:any){versionError.value=e.message}finally{loadingVersions.value=false}}
async function enter(){await nextTick();if(scroller.value)scroller.value.scrollTop=props.tab.scroll;if(['install','resources'].includes(props.tab.page)&&!versions.value.length)await loadVersions();if(props.tab.page==='settings')cfConfigured.value=await api<boolean>('resource.configure');if(props.tab.page==='plugins')plugins.value=await run('plugins','plugins.list')||[]}
onMounted(enter)
watch(()=>props.tab.id,enter)
watch(()=>props.tab.page,enter)
function edit(i:Instance){editor.value=i;Object.assign(options,{name:i.name,group:i.group,favorite:i.favorite,memory:i.memory,java:i.java,isolated:i.isolated,protected:i.protected,memoryMode:i.memoryMode})}
async function saveInstance(){if(!editor.value)return;const result=await run('instance-save','instance.save',{id:editor.value.id,options:{...options}});if(result){editor.value=null;toast('实例设置已保存')}}
async function favorite(i:Instance){await run(i.id+'star','instance.save',{id:i.id,options:{name:i.name,group:i.group,favorite:!i.favorite,memory:i.memory,java:i.java,isolated:i.isolated,protected:i.protected,memoryMode:i.memoryMode}})}
async function launch(i:Instance){if(!data.state.accounts.length){toast('先添加微软或离线账户，再启动游戏');emit('login');return}const ok=await run(i.id+'launch','instance.launch',i.id);if(ok)toast('启动任务已提交，可在任务中心查看进度')}
async function detect(){java.value=await run('java','java.detect')||[];if(!java.value.length&&!busy.has('java'))toast('尚未找到可用 Java，可手动选择 java.exe')}
async function chooseJava(forInstance=false){const file=await run('java-choose','java.choose');if(file){if(forInstance)options.java=file;else settings.java=file}}
async function saveSettings(){const ok=await run('settings','settings.save',{...settings});if(ok)toast('设置已保存')}
async function install(){const task=await run('install','install',{version:selectedVersion.value,loader:loader.value,loaderVersion:loaderVersion.value,loaderSource:loaderSource.value,fabricApi:fabricApi.value,java:installJava.value,sourceId:source.value});if(task){toast('安装已加入任务中心');emit('navigate','tasks')}}
async function removeRecord(){if(!removeTarget.value)return;const result=await run('remove','instance.remove',removeTarget.value.id);if(result){removeTarget.value=null;toast('已移除记录，游戏文件仍在原目录')}}
async function deleteFiles(){if(!removeTarget.value)return;const result=await run('delete','instance.delete',removeTarget.value.id);if(result){removeTarget.value=null;toast('实例目录已移至回收站')}}
const date=(s?:string)=>s?new Date(s).toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'尚未启动'
const isInstance=computed(()=>tab.value.page==='instances')
</script>

<template>
  <div class="page" :data-page="tab.page">
    <header class="page-header"><div><h1>{{pages[tab.page].title}}<span v-if="isInstance" class="count">{{data.instances.length}}</span></h1><p>{{pages[tab.page].sub}}</p></div><button v-if="isInstance" class="button primary compact" @click="run('source','source.add')"><Icon name="folderPlus" :size="16"/>添加目录</button><button v-else-if="tab.page==='tasks'" class="button icon-button" title="导出日志" @click="run('export','logs.export')"><Icon name="download"/></button><span v-else class="header-symbol"><Icon :name="tab.page" :size="26"/></span></header>

    <div v-if="isInstance" class="instance-toolbar"><div class="search-field"><Icon name="search" :size="16"/><input v-model="tab.query" placeholder="搜索实例、版本或目录路径…" aria-label="搜索实例"/><button v-if="tab.query" class="bare" @click="tab.query=''"><Icon name="x" :size="14"/></button><kbd>/</kbd></div><div class="filter-row"><div class="segmented"><button :class="{active:filter==='all'}" @click="filter='all'">全部</button><button :class="{active:filter==='favorite'}" @click="filter='favorite'"><Icon name="star" :size="13"/>收藏</button><button :class="{active:filter==='running'}" @click="filter='running'">运行中<span v-if="running" class="mini-count">{{running}}</span></button></div><select v-model="tab.group" aria-label="实例分组"><option value="">所有分组</option><option v-for="g in groups" :key="g">{{g}}</option></select><button class="bare" title="重新扫描" :disabled="busy.has('scan')" @click="run('scan','scan')"><Icon name="refresh" :class="{spin:busy.has('scan')}" :size="16"/></button></div><div class="filter-row instance-sort-row"><select v-model="loaderFilter" aria-label="按加载器筛选"><option value="">所有加载器</option><option v-for="loader in ['Vanilla','Fabric','Forge','NeoForge','Quilt','OptiFine','LiteLoader']" :key="loader" :value="loader">{{loader==='Vanilla'?'原版':loader}}</option></select><select v-model="sortOrder" aria-label="实例排序"><option value="favorite">收藏优先</option><option value="name">按名称排序</option><option value="recent">最近启动优先</option><option value="version">游戏版本从新到旧</option></select><button class="bare" :class="{selected:filter==='recent'}" @click="filter=filter==='recent'?'all':'recent'">最近启动</button></div></div>

    <div ref="scroller" class="page-scroll" @scroll="tab.scroll=($event.target as HTMLElement).scrollTop">
      <template v-if="isInstance">
        <div v-if="!data.state.sources.length" class="welcome-card"><div class="terrain"><div class="sun-dot"></div><div class="mountain mountain-back"></div><div class="mountain mountain-front"></div><div class="terrain-grid"></div><span class="terrain-mark">H</span></div><div class="welcome-copy"><span class="small-label">一切准备就绪</span><h2>把你的世界带进来。</h2><p>添加现有的 Minecraft 文件夹，<br>或安装一个全新的游戏实例。</p><div class="button-row"><button class="button primary" @click="run('source','source.add')"><Icon name="folderPlus" :size="16"/>添加游戏目录</button><button class="button subtle" @click="emit('navigate','install')">安装游戏<Icon name="arrow" :size="16"/></button></div></div></div>
        
        <div v-if="data.scanWarnings.length" class="inline-notice"><Icon name="warning" :size="16"/><div v-for="w in data.scanWarnings" :key="w">{{w}}</div></div>
        <div v-if="data.state.sources.length" class="list-heading"><span>{{filter==='favorite'?'已收藏的实例':filter==='running'?'正在运行':'所有实例'}}</span><span>{{filtered.length}} 个实例</span></div>
        <div v-for="instance in filtered" :key="instance.id" class="instance-card" :class="{running:instance.running,broken:instance.issue}">
          <div class="instance-top"><div class="block-icon" :class="instance.loader.toLowerCase()"><Icon :name="instance.loader==='Vanilla'?'package':'instances'" :size="24"/></div><div class="instance-meta"><h3 :title="instance.name">{{instance.name}}</h3><div class="instance-tags"><span class="loader-tag" :class="instance.loader.toLowerCase()">{{instance.loader==='Vanilla'?'原版':instance.loader}}</span><span>{{instance.minecraft}}</span><span v-if="instance.group">· {{instance.group}}</span></div></div><button class="bare favorite" :class="{selected:instance.favorite}" :title="instance.favorite?'取消收藏':'收藏实例'" @click="favorite(instance)"><Icon name="star" :size="16"/></button></div>
          <div v-if="instance.protected" class="protected-label"><Icon name="shield" :size="12"/>已保护</div><div v-if="instance.issue" class="instance-issue"><Icon name="warning" :size="13"/>{{instance.issue}}</div>
          <div class="instance-bottom"><span v-if="instance.running" class="running-label"><i/>运行中</span><span v-else class="last-played">{{date(instance.lastPlayed)}}</span><div class="instance-actions"><button class="bare" title="打开游戏目录" @click="run(instance.id+'open','instance.open',instance.id)"><Icon name="folder" :size="15"/><span>目录</span></button><button class="action" @click="modInstance=instance"><Icon name="package" :size="14"/>Mod</button><button class="action" :disabled="!!instance.running" @click="edit(instance)"><Icon name="sliders" :size="14"/>设置</button><button class="action danger-text" :disabled="!!instance.running||instance.protected" :title="instance.protected?'请先在设置中解除实例保护':'删除实例'" @click="removeTarget=instance"><Icon name="trash" :size="14"/>删除</button><button v-if="instance.running" class="button stop-button compact" @click="run(instance.id+'stop','instance.stop',instance.id)"><Icon name="stop" :size="13"/>结束</button><button v-else class="button primary compact" :disabled="!!instance.issue||busy.has(instance.id+'launch')" @click="launch(instance)"><Icon name="play" :size="13"/>启动</button></div></div>
        </div>
        <div v-if="data.state.sources.length&&!filtered.length" class="empty-state"><Icon name="search" :size="32"/><h3>{{data.instances.length?'没有匹配的实例':'还没有识别到实例'}}</h3><p>{{data.instances.length?'试试其他关键词，或切换分组与筛选。':'请选择含 versions 的游戏目录，或先安装游戏。'}}</p><button class="button" @click="emit('navigate','install')">前往安装游戏<Icon name="arrow" :size="15"/></button></div>
        <div class="collection-footer"><Icon name="drive" :size="14"/><span>{{data.state.sources.length?'已连接 '+data.state.sources.length+' 个游戏目录':'支持多个目录 · 保留现有文件位置'}}</span><button v-if="data.state.sources.length" class="bare" @click="emit('navigate','settings')">管理<Icon name="right" :size="13"/></button></div>
      </template>

      <template v-else-if="tab.page==='install'||tab.page==='resources'">
<div class="download-tabs segmented"><button v-for="c in [{id:'game',label:'游戏'},{id:'mod',label:'Mod'},{id:'resourcepack',label:'资源包'},{id:'shader',label:'光影'}]" :key="c.id" :class="{active:downloadKind===c.id}" @click="downloadKind=c.id">{{c.label}}</button></div><ResourceBrowser v-if="downloadKind!=='game'" :key="tab.id+downloadKind" :tab="tab" :kind="resourceKind" @tasks="emit('navigate','tasks')"/><template v-else>
                <section class="section"><div class="section-title"><span class="step-number">01</span><h3>选择游戏版本</h3><button class="bare" title="刷新版本" @click="loadVersions"><Icon name="refresh" :size="15" :class="{spin:loadingVersions}"/></button></div><div class="search-field"><Icon name="search" :size="15"/><input v-model="versionSearch" placeholder="搜索版本，例如 1.21.1" aria-label="搜索游戏版本"/></div><div class="version-options"><label class="check-label"><input v-model="showSnapshots" type="checkbox"/>显示快照与测试版</label><span>{{versions.length}} 个可用版本</span></div><div v-if="loadingVersions" class="loading-row"><Icon name="loading" class="spin" :size="18"/>正在获取官方版本列表…</div><div v-else-if="versionError" class="inline-notice"><Icon name="warning"/><p>{{versionError}}</p><button class="button" @click="loadVersions">重试</button></div><div v-else class="version-list"><button v-for="v in releaseList" :key="v.id" class="version-item" :class="{selected:selectedVersion===v.id}" @click="selectedVersion=v.id"><span class="radio-mark"><i/></span><b>{{v.id}}</b><span v-if="v.id===versions.find(v=>v.type==='release')?.id" class="latest-label">最新正式版</span><span class="version-date">{{new Date(v.releaseTime).toLocaleDateString('zh-CN')}}</span></button><div v-if="!releaseList.length" class="loading-row">没有匹配版本</div></div></section>
        <section class="section"><div class="section-title"><span class="step-number">02</span><h3>选择加载器和组件</h3></div><div class="loader-choices loader-grid"><button v-for="kind in loaderKinds" :key="kind" :aria-label="'选择 '+loaderNames[kind]" :class="{selected:loader===kind}" @click="loader=kind"><div><b>{{loaderNames[kind]}}</b><p>{{kind==='vanilla'?'不安装模组加载器':kind==='optifine'?'独立安装 · 优化与光影':kind==='liteloader'?'旧版本专用':'选择兼容的组件版本'}}</p></div><Icon v-if="loader===kind" name="check" :size="17"/></button></div><template v-if="loader!=='vanilla'"><div class="resource-filters loader-filters"><label>下载源<select v-model="loaderSource" aria-label="加载器下载源"><option value="auto">自动：官方优先，失败使用 BMCLAPI</option><option value="official">仅官方</option><option value="mirror">BMCLAPI</option></select></label><button class="button compact" :disabled="loadingLoaders" @click="loadLoaders(true)">刷新组件列表</button></div><div v-if="loadingLoaders" class="loading-row">正在获取 {{loaderNames[loader as LoaderKind]}} 兼容版本…</div><div v-if="loaderError" class="inline-notice" role="alert">{{loaderError}}</div><select v-model="loaderVersion" class="full-input" aria-label="加载器版本" :disabled="loadingLoaders"><option value="">{{loaderVersions.length?'请选择组件版本':'此游戏版本暂无可用组件'}}</option><option v-if="loaderVersion&&!visibleLoaders.some(v=>v.version===loaderVersion)" :value="loaderVersion">{{loaderVersion}} · 已选择的测试版</option><option v-for="v in visibleLoaders" :key="v.version" :value="v.version">{{v.version}} {{v.recommended?'· 推荐':''}} {{v.stable?'':'· 测试版'}} {{v.detail?'· '+v.detail:''}} · {{v.source}}</option></select><label class="check-label loader-tests"><input v-model="showLoaderTests" type="checkbox"/>显示测试版 / 快照组件</label><label v-if="loader==='fabric'" class="check-label loader-tests"><input v-model="fabricApi" type="checkbox"/>同时安装兼容的 Fabric API（Modrinth）</label><p v-if="loader==='optifine'" class="field-hint">本轮提供独立 OptiFine 实例；不允许将不确定兼容的组件组合安装。</p><p v-if="loader==='liteloader'" class="field-hint">仅适用于部分 1.12.2 及更早游戏，版本目录与文件来自 BMCLAPI。</p><div v-if="['forge','neoforge','optifine'].includes(loader)" class="install-java"><label class="field-label">安装所需 Java：{{javaRule.min}}{{javaRule.max===javaRule.min?'':'–'+javaRule.max}}</label><JavaPicker v-model="installJava" inherit/><p class="field-hint">自动匹配或手动指定。安装前会检查版本范围，不会自动下载 Java。</p></div></template></section>
        <section class="section"><div class="section-title"><span class="step-number">03</span><h3>安装位置</h3></div><select v-model="source" class="full-input" aria-label="安装目录"><option value="">程序目录 / data / minecraft</option><option v-for="s in data.state.sources" :key="s.id" :value="s.id">{{s.label}} — {{s.path}}</option></select><p class="field-hint">新实例默认隔离游戏目录，存档与模组分别管理。</p></section>
        <div class="install-summary"><div><span>准备安装</span><b>{{selectedVersion||'请选择版本'}}<small> · {{loaderNames[loader as LoaderKind]}}{{loaderVersion?' '+loaderVersion:''}}</small></b></div><button class="button primary" :disabled="!selectedVersion||busy.has('install')||loadingLoaders||(loader!=='vanilla'&&!loaderVersion)" @click="install"><Icon name="download" :size="17"/>开始安装</button></div>
      </template></template>

      <template v-else-if="tab.page==='tasks'">
        <div class="stats-strip"><div><b>{{data.tasks.filter(t=>t.status==='running').length}}</b><span>正在进行</span></div><div><b>{{data.tasks.filter(t=>t.status==='success').length}}</b><span>已经完成</span></div><div><b>{{data.tasks.filter(t=>t.status==='error').length}}</b><span>需要处理</span></div></div>
        <div v-if="!data.tasks.length" class="quiet-state"><Icon name="success" :size="32"/><h3>此刻，一切就绪</h3><p>下载与启动任务会显示在这里。</p></div>
        <div v-for="t in [...data.tasks].reverse()" :key="t.id" class="task-card"><Icon :name="t.status==='running'?'loading':t.status==='error'?'warning':t.status==='success'?'success':'x'" :class="[t.status,{spin:t.status==='running'}]" :size="20"/><div class="task-content"><div><b>{{t.title}}</b><span>{{{running:'进行中',success:'已完成',error:'失败',cancelled:'已取消'}[t.status]}}</span></div><p>{{t.detail}}</p><div v-if="t.status==='running'" class="progress"><i :style="{width:t.progress+'%'}"/></div></div><button v-if="t.status==='running'" class="bare" title="取消任务" @click="run(t.id,'task.cancel',t.id)"><Icon name="x" :size="16"/></button></div>
        <section class="section log-section"><div class="section-title"><Icon name="terminal" :size="17"/><h3>实时日志</h3><label class="check-label"><input v-model="autoScroll" type="checkbox"/>跟随</label></div><div class="log-filters"><input v-model="logFilter" placeholder="搜索日志…" aria-label="搜索日志"/><select v-model="logScope" aria-label="日志来源"><option value="">所有来源</option><option v-for="i in data.instances" :key="i.id" :value="i.id">{{i.name}}</option></select><label class="check-label"><input v-model="onlyErrors" type="checkbox"/>错误</label></div><div ref="logElement" class="log-console"><div v-if="!visibleLogs.length" class="muted">等待日志输出…</div><div v-for="(l,index) in visibleLogs" :key="index" :class="{error:l.level==='error'}"><time>{{new Date(l.time).toLocaleTimeString('zh-CN',{hour12:false})}}</time><span>{{l.text}}</span></div></div></section>
      </template>

      <template v-else-if="tab.page==='settings'">
        <section class="section"><div class="section-title"><Icon name="monitor"/><h3>外观与体验</h3></div><div class="setting-row"><div><b>界面主题</b><p>让工作区适应你的习惯</p></div><div class="segmented"><button :class="{active:data.state.settings.theme==='dark'}" @click="changeAppearance({theme:'dark'})"><Icon name="moon" :size="14"/>深色</button><button :class="{active:data.state.settings.theme==='light'}" @click="changeAppearance({theme:'light'})"><Icon name="sun" :size="14"/>浅色</button></div></div><div class="setting-row accent-setting"><div><b>主题配色</b><p>即时生效并自动保存，也可以自定义颜色</p></div><div class="accent-picker"><button v-for="preset in accentPresets" :key="preset.color" class="accent-swatch" :class="{selected:data.state.settings.accent.toLowerCase()===preset.color}" :style="{background:preset.color}" :title="preset.name" :aria-label="preset.name" @click="changeAppearance({accent:preset.color})"><Icon v-if="data.state.settings.accent.toLowerCase()===preset.color" name="check" :size="13"/></button><label class="custom-accent" title="自定义主题色"><input type="color" aria-label="自定义主题色" :value="data.state.settings.accent" @change="changeAppearance({accent:($event.target as HTMLInputElement).value})"/></label></div></div><label class="setting-row font-setting"><div><b>字体大小</b><p>{{data.state.settings.fontScale}}% · 立即生效</p></div><input aria-label="字体大小" class="range" type="range" min="90" max="150" step="5" :value="data.state.settings.fontScale" @input="changeAppearance({fontScale:Number(($event.target as HTMLInputElement).value)})"/></label><label class="setting-row"><div><b>减少动态效果</b><p>关闭界面过渡动画</p></div><input :checked="data.state.settings.reduceMotion" class="switch" type="checkbox" @change="changeAppearance({reduceMotion:($event.target as HTMLInputElement).checked})"/></label></section>
        <section class="section"><div class="section-title"><Icon name="java"/><h3>默认启动设置</h3></div><label class="field-label">内存分配方式</label><select v-model="settings.memoryMode" class="full-input" aria-label="全局内存分配方式"><option value="auto">自动分配（启动前计算）</option><option value="manual">手动分配</option></select><p v-if="settings.memoryMode==='auto'" class="field-hint">根据可用内存、Java 位数和模组规模分配，并为系统预留空间。实际分配量见启动日志。</p><label v-if="settings.memoryMode==='manual'" class="field-label">内存上限 <b>{{settings.memory}} MB</b></label><input v-if="settings.memoryMode==='manual'" v-model.number="settings.memory" aria-label="手动内存上限" class="range" type="range" min="512" :max="Math.min(65536,data.memoryMb)" step="512"/><p class="field-hint">系统总内存 {{(data.memoryMb/1024).toFixed(1)}} GB。每个实例也可单独配置。</p><label class="field-label">Java 路径</label><JavaPicker v-model="settings.java"/></section>
        <section class="section"><div class="section-title"><Icon name="shield"/><h3>Microsoft 正版登录</h3></div><p class="field-hint">当前使用{{data.authSource==='builtin'?'内置的公共客户端 ID':'已配置的应用 ID'}} <span class="mono">{{data.authClientId}}</span>，登录时无需填写任何内容。授权页面会显示提供该 ID 的应用名称。</p><details class="login-configuration"><summary>使用自己的应用 ID（可选）</summary><input v-model="settings.clientId" class="full-input mono" aria-label="自定义 Microsoft 应用 Client ID" placeholder="留空则使用内置 ID"/><p class="field-hint">填写后立即覆盖内置值。应用需要支持个人 Microsoft 账户、桌面回调 http://localhost 和设备代码，并获准访问 Minecraft 服务；也可以直接在数据目录放入 client-id.txt。</p><button class="text-link" @click="run('registration','open','registration')">打开应用注册管理<Icon name="external" :size="13"/></button></details></section>
        <section class="section"><div class="section-title"><Icon name="resources"/><h3>CurseForge 资源源</h3></div><p class="field-hint">{{cfConfigured?'密钥已配置，可在下载页切换 CurseForge':'尚未配置；Modrinth 可直接使用'}}。密钥使用系统加密保存。</p><input v-model="cfKey" type="password" autocomplete="off" class="full-input" aria-label="CurseForge API 密钥" placeholder="填写项目自己的 API 密钥"/><button class="button compact" @click="saveCf">{{cfKey?'保存密钥':'清除密钥'}}</button></section><section class="section"><div class="section-title"><Icon name="folder"/><h3>游戏目录</h3><button class="bare" title="添加目录" @click="run('source','source.add')"><Icon name="plus" :size="17"/></button></div><div v-for="s in data.state.sources" :key="s.id" class="source-row"><Icon name="folder" :size="18"/><div><b>{{s.label}}</b><p>{{s.path}}</p></div><button class="bare" title="移除目录登记（保留文件）" @click="run(s.id,'source.remove',s.id)"><Icon name="x" :size="15"/></button></div><p v-if="!data.state.sources.length" class="field-hint">尚未添加游戏目录。支持标准 .minecraft、versions 文件夹及独立实例容器。</p></section>
        <section class="section"><div class="section-title"><Icon name="drive"/><h3>便携数据</h3></div><div class="path-box">{{data.dataPath||'程序目录 / data'}}</div><p class="field-hint">配置、日志与缓存保存在程序旁。账户凭据使用系统加密，换电脑后需重新登录。程序目录不可写时会明确报错。</p><button class="button" @click="run('data','open','data')"><Icon name="folder" :size="15"/>打开数据目录</button></section><div class="sticky-actions"><button class="button primary" :disabled="busy.has('settings')" @click="saveSettings"><Icon name="save" :size="16"/>保存设置</button></div>
      </template>

      <template v-else-if="tab.page==='tools'">
        <div class="feature-card"><span class="feature-icon"><Icon name="java" :size="26"/></span><div><h2>找到合适的 Java</h2><p>检测本机运行环境，启动时按版本要求匹配。</p></div></div><button class="button primary" :disabled="busy.has('java')" @click="detect"><Icon name="refresh" :size="16" :class="{spin:busy.has('java')}"/>{{busy.has('java')?'正在检测…':'检测本机 Java'}}</button><div v-for="j in java" :key="j.path" class="java-card"><span class="java-version">{{j.major}}</span><div><b>Java {{j.version}} <small>{{j.arch}}</small></b><p>{{j.path}}</p></div><button class="bare" title="设为默认 Java" @click="settings.java=j.path;saveSettings()"><Icon name="check" :size="17"/></button></div><p v-if="!java.length" class="field-hint">会检查 PATH、JAVA_HOME 及常见安装目录，也可在设置中手动指定。</p><div class="tool-grid"><button @click="run('data','open','data')"><Icon name="drive"/><b>便携数据目录</b><span>配置、缓存与本地数据<Icon name="external" :size="14"/></span></button><button @click="run('logs','open','logs')"><Icon name="terminal"/><b>启动器日志</b><span>查看运行与错误记录<Icon name="external" :size="14"/></span></button><button @click="run('website','open','website')"><Icon name="link"/><b>Minecraft 官网</b><span>访问游戏官方网站<Icon name="external" :size="14"/></span></button><button @click="run('redeem','open','redeem')"><Icon name="package"/><b>兑换游戏代码</b><span>前往官方兑换页面<Icon name="external" :size="14"/></span></button></div>
        <section class="section"><div class="section-title"><Icon name="shield"/><h3>登录缓存</h3></div><p class="field-hint">账户缓存无法解密或登录状态异常时，可清理本机凭据后重新登录。游戏文件保留。</p><button class="button" @click="run('account-reset','account.reset').then(ok=>{if(ok)toast('登录缓存已清理，请重新登录')})"><Icon name="refresh" :size="15"/>清理登录缓存</button></section>
      </template>

      <template v-else-if="tab.page==='plugins'">
        <div class="feature-card"><span class="feature-icon"><Icon name="plugins" :size="26"/></span><div><h2>为启动器增加能力</h2><p>0.1.0 提供命令与启动事件扩展接口。</p></div></div><div v-for="p in plugins" :key="p.id" class="plugin-card"><div class="plugin-heading"><span class="block-icon"><Icon name="plugins" :size="24"/></span><div><h3>{{p.name}}<small>{{p.version}}</small></h3><p>{{p.id}}</p></div><span class="pill">内置</span></div><p>{{p.description}}</p><button v-for="c in p.commands" :key="c.id" class="button" @click="run(c.id,'plugins.command',c.id).then(r=>{if(r)toast('检查完成：发现 '+r.javaCount+' 个可用 Java，详情见日志')})"><Icon name="play" :size="14"/>{{c.title}}</button></div><div class="inline-notice"><Icon name="help" :size="18"/><p>首版扩展以随程序构建的模块加载。外部插件安装、权限管理与独立进程运行将在后续版本提供。</p></div>
      </template>


    </div>
    <Teleport to="body"><ModManager v-if="modInstance" :instance="data.instances.find(i=>i.id===modInstance?.id)||modInstance" @close="modInstance=null" @download="openModDownloads"/><div v-if="editor" class="modal-backdrop" @click.self="editor=null"><section class="modal"><header><div><h2>实例设置</h2></div><button class="bare" aria-label="关闭实例设置" @click="editor=null"><Icon name="x"/></button></header><div class="modal-body"><label class="field-label">实例名称</label><input v-model="options.name" class="full-input"/><label class="field-label">分组</label><input v-model="options.group" class="full-input" placeholder="例如：生存、测试、模组整合" list="group-names"/><datalist id="group-names"><option v-for="g in groups" :key="g" :value="g"/></datalist><label class="field-label">内存分配方式</label><select v-model="options.memoryMode" class="full-input" aria-label="实例内存分配方式"><option value="inherit">使用全局设置</option><option value="auto">自动分配</option><option value="manual">手动分配</option></select><label v-if="options.memoryMode==='manual'" class="field-label">内存上限 <b>{{options.memory}} MB</b></label><input v-if="options.memoryMode==='manual'" v-model.number="options.memory" aria-label="实例手动内存上限" class="range" type="range" min="512" :max="Math.min(65536,data.memoryMb)" step="512"/><label class="field-label">Java 路径</label><JavaPicker v-model="options.java" inherit/><label class="setting-row"><div><b>保护此实例</b><p>阻止删除、移除记录以及覆盖安装此版本；启动与查看保持可用。</p></div><input v-model="options.protected" class="switch" type="checkbox" aria-label="保护此实例"/></label><label class="setting-row"><div><b>隔离游戏目录</b><p>启用后使用 versions / 版本名 作为游戏目录</p></div><input v-model="options.isolated" class="switch" type="checkbox"/></label><p class="field-hint">切换隔离模式会改变所用的存档和模组位置，不会自动迁移文件。</p><div class="path-box">{{editor.root}}</div></div><footer><button class="button" @click="editor=null">取消</button><button class="button primary" :disabled="busy.has('instance-save')||!options.name.trim()" @click="saveInstance">保存设置</button></footer></section></div>
    <div v-if="removeTarget" class="modal-backdrop" @click.self="removeTarget=null"><section class="modal small-modal"><header><h2>删除实例</h2><button class="bare" aria-label="关闭删除确认" @click="removeTarget=null"><Icon name="x"/></button></header><div class="modal-body"><div class="delete-illustration"><Icon name="trash" :size="28"/></div><h3>{{removeTarget.name}}</h3><p>选择如何处理此实例。删除文件前还会确认完整路径。</p><button class="delete-option" :disabled="busy.has('remove')" @click="removeRecord"><Icon name="x"/><div><b>仅移除记录</b><p>保留全部游戏文件，重新添加目录后可识别。</p></div><Icon name="right"/></button><button class="delete-option danger-text" :disabled="busy.has('delete')" @click="deleteFiles"><Icon name="trash"/><div><b>将实例目录移至回收站</b><p>包括该版本目录中的独立存档与模组。</p></div><Icon name="right"/></button></div></section></div></Teleport>
  </div>
</template>
